OBJ_SOURCE='"""Paper objective measures, computed on complete rollout before DP sharding.\n\nWeights survive row permutations. Mini batches estimate the complete rollout\nobjective by uniformly sampling rows; no local-rank question re-normalization.\n"""\nfrom collections import defaultdict\nimport torch\nfrom verl.utils import torch_functional as F\n\n\n@torch.no_grad()\ndef attach_policy_weights(data, method):\n    width = data.batch[\'responses\'].shape[1]\n    mask = (data.batch[\'attention_mask\'][:, -width:] * data.batch[\'info_mask\'][:, -width:]).float()\n    weights = torch.zeros_like(mask)\n    if method == \'topd\':\n        groups = defaultdict(list)\n        for i, uid in enumerate(data.non_tensor_batch[\'uid\']):\n            groups[uid].append(i)\n        # Empty questions remain in the outer expectation with zero contribution.\n        scale = len(data) / max(1, len(groups))\n        for rows in groups.values():\n            count = mask[rows].sum()\n            if count > 0:\n                weights[rows] = mask[rows] * scale / count\n    elif method == \'gigpo\':\n        for i in range(len(data)):\n            steps = data.batch[\'step_ids\'][i]\n            actions = torch.unique(steps[mask[i].bool()])\n            if (actions < 0).any():\n                raise ValueError(\'A supervised GiGPO token has no action ID\')\n            for step in actions:\n                selected = (steps == step) & mask[i].bool()\n                weights[i, selected] = 1. / (len(actions) * selected.sum())\n    elif method in (\'tree_grpo\', \'cosearch\'):\n        weights = mask / mask.sum(-1, keepdim=True).clamp_min(1)\n    else:\n        raise ValueError(f\'No paper policy measure for {method}\')\n    data.batch[\'policy_weights\'] = weights\n    return data\n\n\ndef reduce_paper_metrics(metrics, device):\n    """Make detached objective logs identical before DataProto keeps rank zero.\n\n    Each rank\'s contributions already use the global row/mass denominator\n    divided by world size, so averaging them recovers the full minibatch value.\n    This collective only touches logs and does not rescale loss or gradients.\n    """\n    if not torch.distributed.is_initialized():\n        return\n    keys = [key for key in (\'actor/pg_loss\', \'actor/entropy_loss\', \'actor/kl_loss\',\n                            \'actor/pg_clipfrac\', \'actor/ppo_kl\') if key in metrics]\n    if not keys:\n        return\n    sizes = [len(metrics[key]) for key in keys]\n    values = torch.tensor([value for key in keys for value in metrics[key]],\n                          dtype=torch.float64, device=device)\n    torch.distributed.all_reduce(values, op=torch.distributed.ReduceOp.SUM)\n    values /= torch.distributed.get_world_size()\n    offset = 0\n    for key, size in zip(keys, sizes):\n        metrics[key] = values[offset:offset + size].tolist()\n        offset += size\n\n\ndef row_denominator(rows, device):\n    count = torch.tensor(float(rows), device=device)\n    world = 1\n    if torch.distributed.is_initialized():\n        torch.distributed.all_reduce(count, op=torch.distributed.ReduceOp.SUM)\n        world = torch.distributed.get_world_size()\n    return count.clamp_min(1) / world\n\n\ndef weighted_policy_loss(old, current, advantages, mask, weights, cliprange, denominator, step_ids=None):\n    """Token PPO, or GiGPO\'s joint textual-action ratio (Eq.9), with row measure."""\n    valid = mask.bool()\n    for name, value in [(\'old\', old), (\'current\', current), (\'advantage\', advantages), (\'weight\', weights)]:\n        if not torch.isfinite(value[valid]).all():\n            raise ValueError(f\'Nonfinite policy {name} on a supervised token\')\n    old = torch.where(valid, old, 0.)\n    current = torch.where(valid, current, 0.)\n    advantages = torch.where(valid, advantages, 0.)\n    weights = torch.where(valid, weights, 0.)\n    delta = current - old\n    if step_ids is not None:\n        action_deltas = []\n        for i in range(len(delta)):\n            row = delta[i] * 0\n            for step in torch.unique(step_ids[i][valid[i]]):\n                selected = (step_ids[i] == step) & valid[i]\n                if step < 0:\n                    raise ValueError(\'Missing GiGPO action metadata\')\n                action_advantages = advantages[i][selected]\n                if not torch.allclose(action_advantages, action_advantages[:1].expand_as(action_advantages)):\n                    raise ValueError(\'GiGPO advantage must be constant within one textual action\')\n                row = row + selected * delta[i][selected].sum()\n            action_deltas.append(row)\n        delta = torch.stack(action_deltas)\n    ratio = delta.exp()\n    if not torch.isfinite(ratio[valid]).all():\n        raise ValueError(\'Policy ratio overflow on a supervised action/token\')\n    loss1 = -advantages * ratio\n    loss2 = -advantages * ratio.clamp(1 - cliprange, 1 + cliprange)\n    loss = F.masked_sum(torch.maximum(loss1, loss2), weights) / denominator\n    mass = weights.sum()\n    safe_mass = torch.where(mass > 0, mass, torch.ones_like(mass))\n    clipfrac = F.masked_sum((loss2 > loss1).float(), weights) / safe_mass\n    kl = F.masked_sum(-delta, weights) / safe_mass\n    return loss, clipfrac, kl\n'
ACTOR_SOURCE='# Copyright 2024 Bytedance Ltd. and/or its affiliates\n#\n# Licensed under the Apache License, Version 2.0 (the "License");\n# you may not use this file except in compliance with the License.\n# You may obtain a copy of the License at\n#\n#     http://www.apache.org/licenses/LICENSE-2.0\n#\n# Unless required by applicable law or agreed to in writing, software\n# distributed under the License is distributed on an "AS IS" BASIS,\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n# See the License for the specific language governing permissions and\n# limitations under the License.\n"""\nSingle Process Actor\n"""\n\nimport itertools\nfrom typing import Iterable, Tuple\n\nimport torch\nfrom torch import nn\nfrom torch.distributed.fsdp import FullyShardedDataParallel as FSDP\n\nfrom verl import DataProto\nfrom verl.trainer.ppo import core_algos\nfrom verl.workers.actor import BasePPOActor\nfrom verl.utils.py_functional import append_to_dict\nfrom verl.utils.torch_functional import logprobs_from_logits, masked_mean\nfrom verl.utils.ulysses import ulysses_pad_and_slice_inputs, gather_outpus_and_unpad\nfrom verl.utils.seqlen_balancing import rearrange_micro_batches, get_reverse_idx\nimport verl.utils.torch_functional as verl_F\n\n\n__all__ = [\'DataParallelPPOActor\']\n\n\nclass DataParallelPPOActor(BasePPOActor):\n\n    def __init__(\n        self,\n        config,\n        actor_module: nn.Module,\n        actor_optimizer: torch.optim.Optimizer = None,\n    ):\n        """When optimizer is None, it is Reference Policy"""\n        super().__init__(config)\n        self.actor_module = actor_module\n        self.actor_optimizer = actor_optimizer\n        self.use_remove_padding = self.config.get(\'use_remove_padding\', False)\n        print(f\'Actor use_remove_padding={self.use_remove_padding}\')\n        self.ulysses_sequence_parallel_size = self.config.ulysses_sequence_parallel_size\n        self.use_ulysses_sp = self.ulysses_sequence_parallel_size > 1\n\n        self.compute_entropy_from_logits = torch.compile(verl_F.entropy_from_logits, dynamic=True)\n\n    def _forward_micro_batch(self, micro_batch, temperature) -> Tuple[torch.Tensor, torch.Tensor]:\n        """\n        Returns: \n            entropy: # (bs, response_len)\n            log_probs: # (bs, response_len)\n        """\n        response_length = micro_batch[\'responses\'].size(-1)\n        with torch.autocast(device_type=\'cuda\', dtype=torch.bfloat16):\n            input_ids = micro_batch[\'input_ids\']\n            batch_size, seqlen = input_ids.shape\n            attention_mask = micro_batch[\'attention_mask\']\n            position_ids = micro_batch[\'position_ids\']\n\n            if self.use_remove_padding:\n                from flash_attn.bert_padding import pad_input, unpad_input, rearrange, index_first_axis\n                input_ids_rmpad, indices, *_ = unpad_input(input_ids.unsqueeze(-1),\n                                                           attention_mask)  # input_ids_rmpad (total_nnz, ...)\n                input_ids_rmpad = input_ids_rmpad.transpose(0, 1)  # (1, total_nnz)\n\n                # unpad the position_ids to align the rotary\n                position_ids_rmpad = index_first_axis(rearrange(position_ids.unsqueeze(-1), "b s ... -> (b s) ..."),\n                                                      indices).transpose(0, 1)\n\n                # for compute the log_prob\n                input_ids_rmpad_rolled = torch.roll(input_ids_rmpad, shifts=-1, dims=1)  # (1, total_nnz)\n\n                # pad and slice the inputs if sp > 1\n                if self.use_ulysses_sp:\n                    input_ids_rmpad, position_ids_rmpad, pad_size = ulysses_pad_and_slice_inputs(input_ids_rmpad, \\\n                                                                                                position_ids_rmpad, \\\n                                                                                                sp_size=self.ulysses_sequence_parallel_size)\n                    input_ids_rmpad_rolled, _, _ = ulysses_pad_and_slice_inputs(input_ids_rmpad_rolled, None,\n                                                                                self.ulysses_sequence_parallel_size)\n\n                input_ids_rmpad_rolled = input_ids_rmpad_rolled.squeeze(0)  # ((total_nnz / sp) + pad)\n\n                # only pass input_ids and position_ids to enable flash_attn_varlen\n                output = self.actor_module(input_ids=input_ids_rmpad,\n                                           attention_mask=None,\n                                           position_ids=position_ids_rmpad,\n                                           use_cache=False)  # prevent model thinks we are generating\n                logits_rmpad = output.logits.squeeze(0)  # (total_nnz, vocab_size)\n\n                logits_rmpad.div_(temperature)\n\n                # compute entropy\n                entropy_rmpad = self.compute_entropy_from_logits(logits_rmpad)  # ((total_nnz / sp) + pad)\n\n                # if use_sp: ((total_nnz / sp) + pad) ; if not use_sp: (batch, seqlen)\n                log_probs = logprobs_from_logits(logits=logits_rmpad, labels=input_ids_rmpad_rolled)\n\n                # gather log_prob if sp > 1\n                if self.use_ulysses_sp:\n                    # gather and unpad for the ulysses sp\n                    log_probs = gather_outpus_and_unpad(log_probs, gather_dim=0, unpad_dim=0, padding_size=pad_size)\n                    entropy_rmpad = gather_outpus_and_unpad(entropy_rmpad,\n                                                            gather_dim=0,\n                                                            unpad_dim=0,\n                                                            padding_size=pad_size)\n                # pad back to (bsz, seqlen)\n                full_entropy = pad_input(hidden_states=entropy_rmpad.unsqueeze(-1),\n                                         indices=indices,\n                                         batch=batch_size,\n                                         seqlen=seqlen)\n                full_log_probs = pad_input(hidden_states=log_probs.unsqueeze(-1),\n                                           indices=indices,\n                                           batch=batch_size,\n                                           seqlen=seqlen)\n\n                # only return response part:\n                entropy = full_entropy.squeeze(-1)[:, -response_length - 1:-1]  # (bsz, response_length)\n                log_probs = full_log_probs.squeeze(-1)[:, -response_length - 1:-1]  # (bsz, response_length)\n\n            else:  # not using rmpad and no ulysses sp\n                output = self.actor_module(input_ids=input_ids,\n                                           attention_mask=attention_mask,\n                                           position_ids=position_ids,\n                                           use_cache=False)  # prevent model thinks we are generating\n                logits = output.logits\n                logits.div_(temperature)\n                logits = logits[:, -response_length - 1:-1]  # (bsz, response_length)\n                log_probs = logprobs_from_logits(logits, micro_batch[\'responses\'])\n                entropy = verl_F.entropy_from_logits(logits)  # (bsz, response_length)\n\n            return entropy, log_probs\n\n    def _optimizer_step(self):\n        assert self.config.grad_clip is not None\n\n        if isinstance(self.actor_module, FSDP):\n            grad_norm = self.actor_module.clip_grad_norm_(max_norm=self.config.grad_clip)\n        else:\n            grad_norm = torch.nn.utils.clip_grad_norm_(self.actor_module.parameters(), max_norm=self.config.grad_clip)\n        if not torch.isfinite(grad_norm):\n            raise ValueError(\'Nonfinite actor gradient norm; optimizer step refused\')\n        self.actor_optimizer.step()\n        return grad_norm\n\n    def compute_log_prob(self, data: DataProto) -> torch.Tensor:\n        """Compute the log probability of the responses given input_ids, attention_mask and position_ids\n\n        Args:\n            data (DataProto): a DataProto containing keys\n\n                ``input_ids``: tensor of shape [batch_size, sequence_length]. torch.int64. Note that input_ids is the\n                concatenation of prompt and response. Note that ``sequence_length = prompt_length + response_length``.\n\n                ``attention_mask``: tensor of shape [batch_size, sequence_length]. torch.int64.\n\n                ``position_ids``: tensor of shape [batch_size, sequence_length]. torch.int64.\n\n                ``responses``:  tensor of shape [batch_size, response_length]. torch.int64.\n\n        Returns:\n            torch.Tensor: the log_prob tensor\n        """\n        # set to eval\n        self.actor_module.eval()\n\n        micro_batch_size = data.meta_info[\'micro_batch_size\']\n        temperature = data.meta_info[\'temperature\']  # temperature must be in the data.meta_info to avoid slient error\n        use_dynamic_bsz = data.meta_info[\'use_dynamic_bsz\']\n\n        select_keys = [\'responses\', \'input_ids\', \'attention_mask\', \'position_ids\']\n        batch = data.select(batch_keys=select_keys).batch\n\n        if use_dynamic_bsz:\n            # split using dynamic bsz\n            max_token_len = data.meta_info[\'max_token_len\'] * self.ulysses_sequence_parallel_size\n            micro_batches, indices = rearrange_micro_batches(batch=batch, max_token_len=max_token_len)\n        else:\n            micro_batches = batch.split(micro_batch_size)\n\n        log_probs_lst = []\n        for micro_batch in micro_batches:\n            with torch.no_grad():\n                _, log_probs = self._forward_micro_batch(micro_batch, temperature=temperature)\n            log_probs_lst.append(log_probs)\n        log_probs = torch.concat(log_probs_lst, dim=0)\n\n        if use_dynamic_bsz:\n            indices = list(itertools.chain.from_iterable(indices))\n            assert len(indices) == log_probs.size(0), f"{len(indices)} vs. {log_probs.size()}"\n            revert_indices = torch.tensor(get_reverse_idx(indices), dtype=torch.long)\n            log_probs = log_probs[revert_indices]\n\n        return log_probs\n\n    def update_policy(self, data: DataProto):\n        # make sure we are in training mode\n        self.actor_module.train()\n\n        assert self.config.ppo_mini_batch_size % self.config.ppo_micro_batch_size == 0\n        self.gradient_accumulation = self.config.ppo_mini_batch_size // self.config.ppo_micro_batch_size\n        temperature = data.meta_info[\'temperature\']  # temperature must be in the data.meta_info to avoid slient error\n\n        select_keys = [\'responses\', \'input_ids\', \'attention_mask\', \'position_ids\', \'old_log_probs\', \'advantages\']\n        if self.config.state_masking:\n            select_keys.append(\'loss_mask\')\n        if self.config.use_kl_loss:\n            select_keys.append(\'ref_log_prob\')\n        paper_objective = \'policy_weights\' in data.batch.keys()\n        if paper_objective:\n            select_keys.append(\'policy_weights\')\n            if self.config.get(\'baseline_method\') == \'gigpo\':\n                select_keys.append(\'step_ids\')\n        batch = data.select(batch_keys=select_keys).batch\n\n        # Split to make minibatch iterator for updating the actor\n        # See PPO paper for details. https://arxiv.org/abs/1707.06347\n        dataloader = batch.split(self.config.ppo_mini_batch_size)\n\n        metrics = {}\n        updates = skipped = 0\n        # Fixed rollout advantages/logprobs are reused across genuine inner epochs.\n        # Default E=1 preserves the reviewed reproduction\'s update schedule.\n        for batch_idx, data in enumerate(itertools.chain.from_iterable(\n                dataloader for _ in range(self.config.ppo_epochs))):\n            # split batch into micro_batches\n            mini_batch = data\n            from search_r1.baselines.distillation import global_token_count\n            count_mask = mini_batch[\'loss_mask\'] if self.config.state_masking else mini_batch[\'attention_mask\'][:, -mini_batch[\'responses\'].shape[1]:]\n            total, world = global_token_count(count_mask)\n            if total.item() == 0:\n                skipped += 1\n                continue\n            if self.config.get(\'baseline_method\') in (\'gigpo\', \'tree_grpo\', \'topd\', \'cosearch\') and not paper_objective:\n                raise ValueError(\'Paper actor objective requires driver-computed policy_weights\')\n            topd_token_mean = self.config.get(\'baseline_method\') == \'topd\'\n            if paper_objective:\n                from search_r1.baselines.objectives import row_denominator, weighted_policy_loss\n                denominator = row_denominator(len(mini_batch), mini_batch.device)\n                weight_mass, mass_world = global_token_count(mini_batch[\'policy_weights\'])\n                metric_mass = (weight_mass / mass_world).clamp_min(torch.finfo(weight_mass.dtype).tiny)\n            elif topd_token_mean:\n                from search_r1.baselines.advantages import token_mean_ppo\n                denominator = total / world\n            if self.config.use_dynamic_bsz:\n                max_token_len = self.config.ppo_max_token_len_per_gpu * self.ulysses_sequence_parallel_size\n                micro_batches, _ = rearrange_micro_batches(batch=mini_batch, max_token_len=max_token_len)\n            else:\n                # split batch into micro_batches\n                micro_batches = mini_batch.split(self.config.ppo_micro_batch_size)\n\n            self.actor_optimizer.zero_grad()\n            mini_metrics = {}\n\n            for data in micro_batches:\n                data = data.cuda()  # actor device is cpu when using offload\n                responses = data[\'responses\']\n                response_length = responses.size(1)\n                attention_mask = data[\'attention_mask\']\n                response_mask = attention_mask[:, -response_length:]\n                if self.config.state_masking:\n                    response_mask = data[\'loss_mask\']\n                old_log_prob = data[\'old_log_probs\']\n                advantages = data[\'advantages\']\n\n                clip_ratio = self.config.clip_ratio\n                entropy_coeff = self.config.entropy_coeff\n\n                # all return: (bsz, response_length)\n                entropy, log_prob = self._forward_micro_batch(micro_batch=data, temperature=temperature)\n\n                if paper_objective:\n                    pg_loss, pg_clipfrac, ppo_kl = weighted_policy_loss(\n                        old_log_prob, log_prob, advantages, response_mask, data[\'policy_weights\'],\n                        clip_ratio, denominator, data.get(\'step_ids\'))\n                elif topd_token_mean:\n                    pg_loss, pg_clipfrac, ppo_kl = token_mean_ppo(\n                        old_log_prob, log_prob, advantages, response_mask, clip_ratio, denominator)\n                else:\n                    pg_loss, pg_clipfrac, ppo_kl = core_algos.compute_policy_loss(old_log_prob=old_log_prob,\n                                                                                  log_prob=log_prob,\n                                                                                  advantages=advantages,\n                                                                                  eos_mask=response_mask,\n                                                                                  cliprange=clip_ratio)\n                # compute entropy loss from entropy\n                entropy_loss = (verl_F.masked_sum(entropy, data[\'policy_weights\']) / denominator\n                                if paper_objective else verl_F.masked_mean(entropy, response_mask))\n\n                # compute policy loss\n                policy_loss = pg_loss - entropy_loss * entropy_coeff\n\n                if self.config.use_kl_loss:\n                    ref_log_prob = data[\'ref_log_prob\']\n                    # compute kl loss\n                    kld = core_algos.kl_penalty(logprob=torch.where(response_mask.bool(), log_prob, 0.),\n                                                ref_logprob=torch.where(response_mask.bool(), ref_log_prob, 0.),\n                                                kl_penalty=self.config.kl_loss_type)\n                    kl_loss = (verl_F.masked_sum(kld, data[\'policy_weights\']) / denominator\n                               if paper_objective else masked_mean(kld, response_mask))\n\n                    policy_loss = policy_loss + kl_loss * self.config.kl_loss_coef\n                    if paper_objective:\n                        mini_metrics[\'actor/kl_loss\'] = mini_metrics.get(\'actor/kl_loss\', 0.) + kl_loss.detach().item()\n                    else:\n                        metrics[\'actor/kl_loss\'] = kl_loss.detach().item()\n                    metrics[\'actor/kl_coef\'] = self.config.kl_loss_coef\n\n                loss = policy_loss if paper_objective or topd_token_mean else policy_loss / self.gradient_accumulation\n                loss.backward()\n\n                micro_mass = data[\'policy_weights\'].sum().detach().item() if paper_objective else 0.\n                data = {\n                    \'actor/entropy_loss\': entropy_loss.detach().item(),\n                    \'actor/pg_loss\': pg_loss.detach().item(),\n                    \'actor/pg_clipfrac\': pg_clipfrac.detach().item(),\n                    \'actor/ppo_kl\': ppo_kl.detach().item(),\n                }\n                if paper_objective:\n                    for key, value in data.items():\n                        if key in (\'actor/pg_clipfrac\', \'actor/ppo_kl\'):\n                            value *= micro_mass / metric_mass.item()\n                        mini_metrics[key] = mini_metrics.get(key, 0.) + value\n                else:\n                    append_to_dict(metrics, data)\n\n            if paper_objective:\n                append_to_dict(metrics, mini_metrics)\n            grad_norm = self._optimizer_step()\n            updates += 1\n            data = {\'actor/grad_norm\': grad_norm.detach().item()}\n            append_to_dict(metrics, data)\n        self.actor_optimizer.zero_grad()\n        metrics[\'actor/optimizer_steps\'] = updates\n        metrics[\'actor/skipped_empty_minibatches\'] = skipped\n        if paper_objective:\n            from search_r1.baselines.objectives import reduce_paper_metrics\n            reduce_paper_metrics(metrics, batch.device)\n        return metrics\n'
